script:
frappe.ui.form.on('Sales Invoice', {
    onload: function(frm) {
        if (!frm.doc.custom_accountant) {
            frm.set_value('custom_accountant', frappe.session.user);
        }
    }
});

frappe.ui.form.on('Sales Invoice', {
    custom_accountant: function(frm) {
        if (frm.doc.custom_accountant) {
            frappe.call({
                method: 'frappe.client.get_value',
                args: {
                    doctype: 'User',
                    filters: { name: frm.doc.custom_accountant },
                    fieldname: ['email', 'full_name']
                },
                callback: function(r) {
                    if (r.message) {
                        frm.set_value('custom_accountant_email', r.message.email);
                        frm.set_value('custom_accountant_name', r.message.full_name || r.message.name);

                    }
                }
            });
        } 
    },
    onload: function(frm) {
        // 页面加载时也尝试填充
        if (frm.doc.custom_accountant && !frm.doc.custom_accountant_email) {
            frm.trigger('custom_accountant');
        }
    }
});
